operations.old:
export function deoptimizeMethod (vm, env, method) {
  requestDeoptimization(vm, env, kSelectiveDeoptimization, unwrapMethodId(method));
}

operations.new:
// Runtime-local only: native ART addresses must never survive this bridge VM.
const selectiveDeoptimizedMethods = new Set();
let globalDeoptimizationApplied = false;

export function deoptimizeMethod (vm, env, method) {
  deoptimizeMethods(vm, env, [method]);
}

/** Decode opaque JNI IDs before short Native-state exclusive ART batches.
 * Successful methods share one process-local registry across single/batch calls.
 */
export function deoptimizeMethods (vm, env, methods, options = {}) {
  if (!Array.isArray(methods)) {
    throw new TypeError('Selective methods must be an array');
  }
  const batchSize = options.batchSize === undefined ? 32 : options.batchSize;
  if (!Number.isInteger(batchSize) || batchSize < 1 || batchSize > 64) {
    throw new RangeError('Selective batchSize must be an integer from 1 to 64');
  }
  const level = getAndroidApiLevel();
  if (level < 24) {
    throw new Error('This API is only available on Android >= 7.0');
  }
  const decoded = [];
  const identities = [];
  const seen = new Set();
  for (const handle of methods) {
    if (handle === null || handle === undefined || typeof handle.isNull !== 'function' || handle.isNull()) {
      throw new TypeError('Selective method handle must be a non-null NativePointer');
    }
    const method = unwrapMethodId(handle);
    if (method === null || method === undefined || typeof method.isNull !== 'function' || method.isNull()) {
      throw new Error('Decoded selective ArtMethod must be non-null');
    }
    const identity = method.toString();
    if (!seen.has(identity)) {
      seen.add(identity);
      decoded.push(method);
      identities.push(identity);
    }
  }
  const strategy = level < 30 ? 'selective_legacy' : 'selective_batch';
  const requested = decoded.length;
  if (globalDeoptimizationApplied || requested === 0) {
    return { count: 0, batches: 0, batch_size: batchSize, strategy,
      skipped: requested, requested_count: requested, already_global: globalDeoptimizationApplied };
  }
  let count = 0, skipped = 0, batches = 0;
  if (level < 30) {
    for (let i = 0; i < decoded.length; i++) {
      if (selectiveDeoptimizedMethods.has(identities[i])) { skipped++; continue; }
      requestDeoptimization(vm, env, kSelectiveDeoptimization, decoded[i]);
      selectiveDeoptimizedMethods.add(identities[i]);
      count++; batches++;
    }
    return { count, batches, batch_size: 1, strategy, skipped, requested_count: requested, already_global: false };
  }
  // Resolve every capability, address and batch before STW. No JNI, reflection,
  // lazy lookup, allocation, registry mutation or user callback runs inside it.
  const api = getApi();
  const instrumentation = api.artInstrumentation;
  if (instrumentation === null || instrumentation === undefined) {
    throw new Error('ART Instrumentation unavailable for selective batch deoptimization');
  }
  if (api['art::ThreadList::SuspendAll'] === undefined || api['art::ThreadList::ResumeAll'] === undefined) {
    throw new Error('ART exclusive suspension API unavailable');
  }
  const deoptimize = api['art::Instrumentation::Deoptimize'];
  if (deoptimize === undefined) {
    throw new Error('ART selective deoptimization API unavailable');
  }
  // Official exported query, when present, also detects other hook engines.
  // Read under the same exclusive lock as mutation to avoid a query/mutate race.
  const isDeoptimized = api['art::Instrumentation::IsDeoptimized'];
  const enableDeopt = api['art::Instrumentation::EnableDeoptimization'];
  const enabledAddress = enableDeopt === undefined ? null :
    instrumentation.add(getArtInstrumentationSpec().offset.deoptimizationEnabled);
  const pending = [];
  for (let i = 0; i < decoded.length; i++) {
    // When ART offers its own query it is authoritative: a different engine may
    // have since undeoptimized a method or reclaimed/reused an old address.
    if (isDeoptimized === undefined && selectiveDeoptimizedMethods.has(identities[i])) { skipped++; continue; }
    pending.push(i);
  }
  for (let offset = 0; offset < pending.length; offset += batchSize) {
    const batchIndices = pending.slice(offset, offset + batchSize);
    const batch = batchIndices.map(i => decoded[i]);
    // Preallocate outside STW; record only integer counters in the native loop.
    const applied = new Uint8Array(batch.length);
    let completed = 0;
    try {
      withAllArtThreadsSuspended(() => {
        if (enableDeopt !== undefined && enabledAddress.readU8() === 0) {
          enableDeopt(instrumentation);
        }
        for (let i = 0; i < batch.length; i++) {
          if (isDeoptimized !== undefined && isDeoptimized(instrumentation, batch[i])) {
            completed++;
            continue;
          }
          deoptimize(instrumentation, batch[i]);
          applied[i] = 1;
          completed++;
        }
      });
      batches++;
    } finally {
      // The helper has already resumed every ART thread, including on failure.
      // Persist successes from a partially completed batch before propagating.
      for (let i = 0; i < completed; i++) {
        selectiveDeoptimizedMethods.add(identities[batchIndices[i]]);
        if (applied[i] === 1) count++; else skipped++;
      }
    }
  }
  return { count, batches, batch_size: batchSize, strategy, skipped,
    requested_count: requested, already_global: false };
}

operations.old:
export function deoptimizeEverything (vm, env) {
  requestDeoptimization(vm, env, kFullDeoptimization);
}

operations.new:
export function deoptimizeEverything (vm, env) {
  if (globalDeoptimizationApplied) {
    return;
  }
  requestDeoptimization(vm, env, kFullDeoptimization);
  // Only a successful original global operation authorizes selective skipping.
  globalDeoptimizationApplied = true;
}

operations.old:
deoptimizeMethod (method) {
  const { vm } = this;
  return deoptimizeMethod(vm, vm.getEnv(), method);
}

operations.new:
deoptimizeMethod (method) {
  const { vm } = this;
  return deoptimizeMethod(vm, vm.getEnv(), method);
}

deoptimizeMethods (methods, options = {}) {
  const { vm } = this;
  return deoptimizeMethods(vm, vm.getEnv(), methods, options);
}

function deoptimizeBootImage(): void;

/** Decode and deoptimize one method handle (hnubl scoped bridge API). */
function deoptimizeMethod(method: NativePointer): void;

/** Short, bounded Native-state ART batches; handles never persist across processes. */
function deoptimizeMethods(methods: NativePointer[], options?: { batchSize?: number }): {
    count: number;
    batches: number;
    batch_size: number;
    strategy: 'selective_batch' | 'selective_legacy';
    skipped: number;
    requested_count: number;
    already_global: boolean;
};
